import { existsSync, readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import { parseSchemaFile } from '../schema/load';
import { estimateProfile } from './estimate';
import { rateGame } from './registry';
import { scoreProfile } from './score';
import { shippedProfiles } from './shipped';
import { validateProfile } from './profile';

// data/schema.json is generated by scripts/extract-schema.ps1; skip until it exists.
const schemaUrl = new URL('../../data/schema.json', import.meta.url);
const schema = existsSync(schemaUrl) ? parseSchemaFile(readFileSync(schemaUrl, 'utf8')) : null;

describe.skipIf(schema === null)('difficulty data against the real schema', () => {
  const games = Object.values(schema?.games ?? {}).filter((g) => !g.hidden);

  it('ships profiles for at least the first six games', () => {
    expect([...shippedProfiles.keys()].sort()).toEqual(
      ['A Link to the Past', 'APQuest', 'Hollow Knight', 'Ocarina of Time', 'Super Metroid', 'Super Mario World'].sort(),
    );
  });

  it.each([...shippedProfiles.values()].map((p) => [p.game, p] as const))('the %s profile is sound and current', (_name, profile) => {
    const game = schema!.games[profile.game];
    expect(game, `${profile.game} is not a game in schema.json`).toBeDefined();
    expect(validateProfile(profile, game!)).toEqual([]);
    expect(profile.apVersion).toBe(schema!.apVersion);
    expect(profile.status).not.toBe('estimated');
  });

  it('every shipped profile gives its default settings exactly its base score', () => {
    for (const profile of shippedProfiles.values()) {
      const game = schema!.games[profile.game]!;
      expect(scoreProfile(profile, game, {}).score, profile.game).toBe(profile.base);
      const allDefaults = Object.fromEntries(Object.keys(profile.options).map((key) => [key, game.options[key]!.default]));
      expect(scoreProfile(profile, game, allDefaults).score, `${profile.game} at written-out defaults`).toBeCloseTo(profile.base, 9);
    }
  });

  it('every estimate built for a real game is sound', () => {
    let estimated = 0;
    for (const game of games) {
      const profile = estimateProfile(game, schema!.apVersion);
      if (profile === null) continue;
      estimated += 1;
      expect(validateProfile(profile, game), game.name).toEqual([]);
    }
    expect(estimated).toBeGreaterThan(20); // games with a trap, hard-mode or difficulty option; the rest stay Not rated
  });

  it('rates every visible game as rated, estimated or not rated, with a score only when there is a reason', () => {
    const counts = { rated: 0, estimated: 0, none: 0 };
    for (const game of games) {
      const rating = rateGame(game, schema!.apVersion, {}, shippedProfiles);
      counts[rating.source] += 1;
      if (rating.source === 'none') expect(rating.score, game.name).toBeNull();
      else {
        expect(rating.score, game.name).not.toBeNull();
        expect(rating.contributions, `${game.name} at defaults`).toEqual([]);
      }
    }
    expect(counts.rated).toBe(6);
    expect(counts.rated + counts.estimated + counts.none).toBe(games.length);
  });

  it('moves in the expected direction on real games', () => {
    const rate = (name: string, values: Record<string, unknown>) => rateGame(schema!.games[name]!, schema!.apVersion, values, shippedProfiles).score!;
    expect(rate('APQuest', { hard_mode: true })).toBeGreaterThan(rate('APQuest', {}));
    expect(rate('A Link to the Past', { swordless: true, timer: 'ohko' })).toBeGreaterThan(rate('A Link to the Past', {}) + 3);
    expect(rate('A Link to the Past', { item_pool: 'easy' })).toBeLessThan(rate('A Link to the Past', {}));
    expect(rate('Super Metroid', { max_difficulty: 'easy' })).toBeLessThan(rate('Super Metroid', {}));
    expect(rate('Ocarina of Time', { damage_multiplier: 'ohko' })).toBeGreaterThan(rate('Ocarina of Time', { damage_multiplier: 'double' }));
    expect(rate('Hollow Knight', { WhitePalace: 'include', DifficultSkips: true })).toBeGreaterThan(rate('Hollow Knight', {}) + 2);
    expect(rate('Super Mario World', { bosses_required: 0 })).toBeLessThan(rate('Super Mario World', {}));
  });
});
